const std = @import("std");
const z = @import("zolver");
fn now() u64 { var ts:std.os.linux.timespec=undefined; _=std.os.linux.clock_gettime(.MONOTONIC,&ts); return @as(u64,@intCast(ts.sec))*1_000_000_000+@as(u64,@intCast(ts.nsec)); }
pub fn main(init:std.process.Init) !void {
    const alloc=std.heap.page_allocator;
    const content=try std.Io.Dir.cwd().readFileAlloc(init.io,"bench/spots/1_srp_dry.toml",alloc,.limited(100000)); defer alloc.free(content);
    var bundle=try z.config.parseConfig(alloc,content); defer bundle.deinit();
    for ([_]u32{1,8}) |nt| {
        var is=try z.init.SolverInit.init(alloc,bundle.game); defer is.deinit();
        var cfg=bundle.solver; cfg.num_threads=nt;
        var solver=try z.cfr.Solver.init(alloc,&is,cfg); defer solver.deinit();
        solver.iterate(2);
        const started=now(); solver.iterate(4); const elapsed=now()-started;
        const gap_started=now(); const gap=z.best_response.exploitabilityGap(&solver); const gap_ns=now()-gap_started;
        std.debug.print("fresh {d}t: {d:.3} ms/iter, two-pass gap {d:.3} ms, exploit={d:.8}%\n",.{nt,@as(f64,@floatFromInt(elapsed))/4e6,@as(f64,@floatFromInt(gap_ns))/1e6,gap.pct});
    }
}
